	// IncludeMatcherSuppressions includes matches that were dropped by
	// hard-coded rules or matcher-provided ignore filters (e.g. distro
	// fixed/NAK records suppressing matches on owned packages) in the
	// ignoredMatches results. When false (the default) these are discarded
	// after logging, preserving the previous behavior.
	IncludeMatcherSuppressions bool

	// tracked packages with distro issues (populated during FindMatches)
	eolDistroPackages     []pkg.Package
	distroDetectionFailed bool
}

func (m *VulnerabilityMatcher) FailAtOrAboveSeverity(severity *vulnerability.Severity) *VulnerabilityMatcher {
	m.FailSeverity = severity
	return m
}

func (m *VulnerabilityMatcher) WithMatchers(matchers []match.Matcher) *VulnerabilityMatcher {
	m.Matchers = matchers
	return m
}

func (m *VulnerabilityMatcher) WithIgnoreRules(ignoreRules []match.IgnoreRule) *VulnerabilityMatcher {
	m.IgnoreRules = ignoreRules
	return m
}

// DistroDetectionFailed returns true if distro detection failed during scanning
// (linux release info was present but distro type could not be determined).
func (m *VulnerabilityMatcher) DistroDetectionFailed() bool {
	return m.distroDetectionFailed
}

// EOLDistroPackages returns packages from distros that have reached end-of-life.
func (m *VulnerabilityMatcher) EOLDistroPackages() []pkg.Package {
	return m.eolDistroPackages
}

// FindMatches finds vulnerabilities for the given packages and package context.
// FindMatches does not support context cancellation; for that, use
// FindMatchesContext.
func (m *VulnerabilityMatcher) FindMatches(
	pkgs []pkg.Package,
	pkgContext pkg.Context,
) (remainingMatches *match.Matches, ignoredMatches []match.IgnoredMatch, err error) {
	return m.FindMatchesContext(context.Background(), pkgs, pkgContext)
}

// FindMatchesContext finds vulnerabilities for the given packages and package
// context, and supports context cancellation.
func (m *VulnerabilityMatcher) FindMatchesContext(
	ctx context.Context,
	pkgs []pkg.Package,
	pkgContext pkg.Context,
) (remainingMatches *match.Matches, ignoredMatches []match.IgnoredMatch, err error) {
	progressMonitor := trackMatcher(len(pkgs))

	// capture distro detection failure from pkgContext for alerting
	m.distroDetectionFailed = pkgContext.DistroDetectionFailed
	if m.distroDetectionFailed {
		log.Warn("distro detection failed: linux release info was present but distro type could not be determined")
	}

	defer func() {
		progressMonitor.Ignored.Set(int64(len(ignoredMatches)))
		progressMonitor.SetCompleted()
		if err != nil {
			progressMonitor.MatchesDiscovered.SetError(err)
		}
	}()

	remainingMatches, ignoredMatches, err = m.findDBMatches(ctx, pkgs, progressMonitor)

